Aquí te proporciono un ejemplo de un programa en C++ que lee un archivo de texto línea por línea y cuenta el número de apariciones de una palabra específica en el archivo:

```cpp
#include <iostream>
#include <fstream>
#include <string>

int main() {
    std::string filename; // Nombre del archivo de texto
    std::string search_word; // Palabra a buscar
    int count = 0; // Contador de apariciones

    // Pedir al usuario el nombre del archivo y la palabra a buscar
    std::cout << "Introduzca el nombre del archivo: ";
    std::cin >> filename;

    std::cout << "Introduzca la palabra a buscar: ";
    std::cin >> search_word;

    // Abrir el archivo de texto
    std::ifstream file(filename);
    if (!file) {
        std::cerr << "Error al abrir el archivo: " << filename << std::endl;
        return 1;
    }

    // Leer línea por línea y contar apariciones
    std::string line;
    while (getline(file, line)) {
        size_t pos = 0;
        while ((pos = line.find(search_word, pos)) != std::string::npos) {
            count++;
            pos += search_word.length();
        }
    }

    // Cerrar el archivo
    file.close();

    // Mostrar el resultado
    std::cout << "El número de apariciones de \"" << search_word << "\" en " << filename << " es: " << count << std::endl;

    return 0;
}
